<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { PaginationContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: PaginationContract  = $props();
const page=control(()=>p.page,untrack(()=>p.defaultPage),1,page=>p.onPageChange?.({page}));let draft=$state(untrack(()=>String(page.value)));let invalid=$state(false);let narrow=$state(false);onMount(()=>{const media=matchMedia('(max-width: 767px)');const update=()=>narrow=media.matches;update();media.addEventListener('change',update);return()=>media.removeEventListener('change',update);});$effect(()=>{draft=String(page.value);invalid=false;});let root:HTMLElement;resetField(()=>root,()=>{draft=String(page.value);invalid=false;});
const numbers=$derived.by<(number|'start-gap'|'end-gap')[]>(()=>{const total=p.pageCount,budget=narrow?7:11;if(total<=budget)return Array.from({length:total},(_,index)=>index+1);const radius=narrow?1:3;let first=Math.max(2,page.value-radius),last=Math.min(total-1,page.value+radius);const size=()=>2+last-first+1+Number(first>2)+Number(last<total-1);while(size()<budget){if(first>2)first--;else if(last<total-1)last++;else break;}return [1,...(first>2?['start-gap' as const]:[]),...Array.from({length:last-first+1},(_,index)=>first+index),...(last<total-1?['end-gap' as const]:[]),total];});let previousShown=untrack(()=>p.loadMore?.shown);$effect(()=>{const shown=p.loadMore?.shown;if(shown!==undefined&&previousShown!==undefined&&shown>previousShown&&p.loadMore?.firstNewItemId){const id=p.loadMore.firstNewItemId;void tick().then(()=>document.getElementById(id)?.focus());}previousShown=shown;});const uid=$props.id();function activate(e:MouseEvent,next:number){if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();page.request(next);}function go(){const next=Number(draft);if(!/^\d+$/.test(draft)||!Number.isSafeInteger(next)||next<1||next>p.pageCount){invalid=true;return;}invalid=false;page.request(next);}
</script>
<nav bind:this={root} {...owned('pagination','root')} data-krds-variant={p.variant??'number-links'} aria-label={p.variant==='load-more'?'결과 더보기':'페이지 이동'}>{#if p.variant==='load-more'}{#if p.loadMore}<p {...owned('pagination','count')} role="status">{p.loadMore.shown} / {p.loadMore.total}</p><button type="button" {...owned('pagination','load-more',p.loadMore.pending&&'pending')} disabled={p.loadMore.pending||p.loadMore.shown>=p.loadMore.total} onclick={event=>{event.currentTarget.focus();p.loadMore?.onLoadMore();}}>더 보기</button>{/if}{:else}{#if page.value>1}<a {...owned('pagination','previous')} href={p.hrefForPage(page.value-1)} rel="prev" onclick={e=>activate(e,page.value-1)}>이전</a>{/if}{#if p.variant==='direct-page'}<label for={`${uid}-input`}>페이지</label><input id={`${uid}-input`} {...owned('pagination','input',invalid&&'invalid')} inputmode="numeric" type="text" bind:value={draft} aria-invalid={invalid||undefined} aria-describedby={invalid?`${uid}-error`:undefined} onkeydown={e=>{if(e.key!=='Enter')return;const ignored=ignoredKey(e);e.preventDefault();if(!ignored)go();}}/><span {...owned('pagination','total')}>/ {p.pageCount}</span><button type="button" {...owned('pagination','go')} onclick={go}>이동</button>{#if invalid}<p id={`${uid}-error`} role="status">1부터 {p.pageCount} 사이의 페이지를 입력하세요.</p>{/if}{:else}<ol {...owned('pagination','list')}>{#each numbers as item(item)}<li {...owned('pagination','item')}>{#if typeof item==='number'}<a {...owned('pagination','link',page.value===item&&'current')} href={page.value===item?undefined:p.hrefForPage(item)} aria-current={page.value===item?'page':undefined} tabindex={page.value===item?-1:undefined} onclick={e=>{if(page.value!==item)activate(e,item);}}>{item}</a>{:else}<span {...owned('pagination','ellipsis')}>…</span>{/if}</li>{/each}</ol>{/if}{#if page.value<p.pageCount}<a {...owned('pagination','next')} href={p.hrefForPage(page.value+1)} rel="next" onclick={e=>activate(e,page.value+1)}>다음</a>{/if}{/if}</nav>
